import java.lang.foreign.*;
import java.lang.invoke.MethodHandle;

public class PanamaDemo {
    public static void main(String[] args) throws Throwable {
        // 1. Open a confined arena for deterministic memory management
        try (Arena arena = Arena.ofConfined()) {
            // 2. Allocate off-heap memory for a C string
            MemorySegment nativeString = arena.allocateUtf8String("Hello from Project Panama!");

            // 3. Look up the standard C library and 'puts' function
            SymbolLookup stdlib = Linker.nativeLinker().defaultLookup();
            MemorySegment putsAddress = stdlib.find("puts").orElseThrow();

            // 4. Link the native function using a downcall descriptor
            Linker linker = Linker.nativeLinker();
            MethodHandle puts = linker.downcallHandle(
                putsAddress,
                FunctionDescriptor.of(ValueLayout.JAVA_INT, ValueLayout.ADDRESS)
            );

            // 5. Invoke the native function safely
            int result = (int) puts.invoke(nativeString);
            System.out.println("Native puts returned: " + result);
        } // Arena closes automatically, freeing native memory safely
    }
}
